@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum MerklRewardsActions {
    public static let creationCode: Hex = ""
    public static let runtimeCode: Hex = ""

    public static let InvalidInputError = ABI.Function(
            name: "InvalidInput",
            inputs: []
    )


    public enum RevertReason : Equatable, Error {
        case invalidInput
        case unknownRevert(String, String)
    }
    public static func rewrapError(_ error: ABI.Function, value: ABI.Value) -> RevertReason {
        switch (error, value) {
        case (InvalidInputError, _):
            return .invalidInput
        case let (e, v):
            return .unknownRevert(e.name, String(describing: v))
        }
    }
    public static let errors: [ABI.Function] = [InvalidInputError]
    public static let functions: [ABI.Function] = [claimFn]
    public static let claimFn = ABI.Function(
            name: "claim",
            inputs: [.address, .array(.address), .array(.address), .array(.uint256), .array(.array(.bytes32))],
            outputs: []
    )

    public static func claim(distributor: EthAddress, accounts: [EthAddress], rewards: [EthAddress], claimables: [Number], proofs: [[Hex]], withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try claimFn.encoded(with: [.address(distributor), .array(.address, accounts.map {
                                    .address($0)
                                }), .array(.address, rewards.map {
                                    .address($0)
                                }), .array(.uint256, claimables.map {
                                    .uint256($0)
                                }), .array(.array(.bytes32), proofs.map {
                                    .array(.bytes32, $0.map {
                                            .bytes32($0)
                                        })
                                })])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try claimFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, claimFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func claimDecode(input: Hex) throws -> (EthAddress, [EthAddress], [EthAddress], [Number], [[Hex]]) {
        let decodedInput = try claimFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple5(.address(distributor), .array(.address, accounts), .array(.address, rewards), .array(.uint256, claimables), .array(.array(.bytes32), proofs)):
            return  (distributor, accounts.map { $0.asEthAddress! }, rewards.map { $0.asEthAddress! }, claimables.map { $0.asNumber! }, proofs.map { $0.asArray!.map { $0.asHex! } })
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, claimFn.inputTuple)
        }
    }

}